declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/task_workflow.php';require_login_any_role(['admin','employee']);$u=current_user();$id=(int)($_GET['id']??0);$db=get_db();$s=$db->prepare('SELECT n.link,n.source_task_id FROM portal_notifications n JOIN portal_notification_status st ON st.notification_id=n.id WHERE n.id=? AND st.user_id=? AND st.status!=\'dismissed\'');$s->execute([$id,(int)$u['id']]);$n=$s->fetch();if(!$n||!task_notification_validate_link((string)$n['link'],(string)$u['role_name'],(int)$n['source_task_id'])){http_response_code(404);echo 'Notification or referenced task is unavailable.';exit;}task_notification_mutate($db,(int)$u['id'],'read',$id);header('Location: '.$n['link'],true,303);exit;
